    'tsconfig.json',
    '{\n  "compilerOptions": {\n    "target": "ES2022",\n    "useDefineForClassFields": true,\n    "module": "ESNext",\n    "lib": ["ES2022", "DOM", "DOM.Iterable"],\n    "skipLibCheck": true,\n    "moduleResolution": "Bundler",\n    "allowImportingTsExtensions": true,\n    "resolveJsonModule": true,\n    "isolatedModules": true,\n    "jsx": "react-jsx",\n    "types": ["vite/client"],\n    "noEmit": true,\n    "strict": true\n  },\n  "include": ["src"]\n}\n',
